selector_to_html = {"a[href=\"#verify-the-triton-setup\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 Verify the Triton setup<a class=\"headerlink\" href=\"#verify-the-triton-setup\" title=\"Link to this heading\">#</a></h3><p>The next verification is against the <code class=\"docutils literal notranslate\"><span class=\"pre\">triton</span></code> package.\nYou can check if <code class=\"docutils literal notranslate\"><span class=\"pre\">triton</span></code> is working as expected using the following\ncommand:</p>", "a[href=\"#install-flaggems\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Install FlagGems<a class=\"headerlink\" href=\"#install-flaggems\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> can be installed either as a pure python package\nor a package with C-extensions for better runtime performance.\nSee <a class=\"reference internal\" href=\"#..//install\"><span class=\"xref myst\">installation</span></a> for some detailed guidance\non different installation options.</p>", "a[href=\"#start-using-flaggems\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Start using FlagGems<a class=\"headerlink\" href=\"#start-using-flaggems\" title=\"Link to this heading\">#</a></h2><p>You can enable the accelerated operators from <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> in many ways.\nThe following code snippet enables <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> globally:</p>", "a[href=\"#verify-pytorch-environment\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 Verify PyTorch environment<a class=\"headerlink\" href=\"#verify-pytorch-environment\" title=\"Link to this heading\">#</a></h3><p>The first thing you want to check is that you can import\n<code class=\"docutils literal notranslate\"><span class=\"pre\">torch</span></code> in your working environment:</p>", "a[href=\"#get-started-with-flaggems\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Get Started With FlagGems<a class=\"headerlink\" href=\"#get-started-with-flaggems\" title=\"Link to this heading\">#</a></h1><h2>1. Install FlagGems<a class=\"headerlink\" href=\"#install-flaggems\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> can be installed either as a pure python package\nor a package with C-extensions for better runtime performance.\nSee <a class=\"reference internal\" href=\"#..//install\"><span class=\"xref myst\">installation</span></a> for some detailed guidance\non different installation options.</p>", "a[href=\"../usage/non-nvidia.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Running FlagGems on Non-NVIDIA Hardware<a class=\"headerlink\" href=\"#running-flaggems-on-non-nvidia-hardware\" title=\"Link to this heading\">#</a></h1><h2>1. Supported platforms<a class=\"headerlink\" href=\"#supported-platforms\" title=\"Link to this heading\">#</a></h2><p>FlagGems supports a range of AI chips/platforms beyond NVIDIA.\nFor an up-to-date list of validated platforms, please refer to\n<a class=\"reference internal\" href=\"../overview/platforms.html\"><span class=\"doc std std-doc\">Supported Platforms</span></a></p>", "a[href=\"#verify-the-installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Verify the installation<a class=\"headerlink\" href=\"#verify-the-installation\" title=\"Link to this heading\">#</a></h2><p>After having installed the <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> package and its dependencies,\nyou may want to verify if they work as expected.</p>", "a[href=\"#verify-the-flaggems-installation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.3 Verify the FlagGems installation<a class=\"headerlink\" href=\"#verify-the-flaggems-installation\" title=\"Link to this heading\">#</a></h3><p>You can do a similar verification for the <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> package,\nusing the following command:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
